# Parameters with modified arm lengths. Every parameter derived from L1/L2 is stored as a separate
# entry in the MTKParameters (the rhs reads e.g. inv_kin and the FixedTranslations by index),
# so all of them are replaced by name. Masses and inertias (J1, J2) are kept unchanged.
function get_SCARAPeNODE_parametersScaledLengths(L1::Float64, L2::Float64)
    param_values, param_names = get_SCARAPeNODE_parameters()
    param_values = deepcopy(param_values)

    new_values = Dict(
        # link 1
        "L1" => L1,
        "inv_kin₊L1" => L1,
        "scara₊L1" => L1,
        "scara₊toRev2₊r[1]" => L1,      # joint 1 -> joint 2
        "scara₊toMass1₊r[1]" => L1 / 2, # joint 1 -> center of mass link 1
        # link 2
        "L2" => L2,
        "inv_kin₊L2" => L2,
        "scara₊L2" => L2,
        "scara₊toTCP₊r[1]" => L2,       # joint 2 -> TCP
        "scara₊toMass2₊r[1]" => L2 / 2, # joint 2 -> center of mass link 2
    )
    for (name, value) in new_values
        idx = findall(==(name), param_names)
        length(idx) == 1 || error("parameter $(name) found $(length(idx)) times")
        param_values.tunable[idx[1]] = value
    end
    return (param_values, param_names)
end

# longer arms: L1 0.2 m -> 0.25 m, L2 0.1 m -> 0.15 m
get_SCARAPeNODE_parametersLengthMod() = get_SCARAPeNODE_parametersScaledLengths(0.25, 0.15)


